import React from "react";

const EventCard = ({ event }) => {
  return (
    <div className="event-card">
      {/* Add this image line (the only important change) */}
      {event.image_url && (
        <img
          src={event.image_url}
          alt={event.title}
          style={{
            width: "100%",
            height: "180px",
            objectFit: "cover",
            borderRadius: "8px"
          }}
        />
      )}

      <h3>{event.title}</h3>
      <p>{event.description}</p>
    </div>
  );
};

export default EventCard;
